+package org.apache.streampipes.rest.security;
+
+import java.net.Inet6Address;
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+import java.util.Locale;
+
+/**
+ * Validates user-provided installation endpoints to prevent SSRF.
+ */
+public final class ExternalEndpointValidator {
+
+  private ExternalEndpointValidator() {
+  }
+
+  public static void validate(String endpointUrl) {
+    URI uri = parse(endpointUrl);
+    String scheme = uri.getScheme() == null ? "" : uri.getScheme().toLowerCase(Locale.ROOT);
+
+    if (!"http".equals(scheme) && !"https".equals(scheme)) {
+      throw new IllegalArgumentException("Invalid endpoint URL");
+    }
+
+    if (uri.getUserInfo() != null) {
+      throw new IllegalArgumentException("Invalid endpoint URL");
+    }
+
+    String host = uri.getHost();
+    if (host == null || host.isBlank()) {
+      throw new IllegalArgumentException("Invalid endpoint URL");
+    }
+
+    InetAddress[] resolved = resolve(host);
+    for (InetAddress address : resolved) {
+      if (isBlockedAddress(address)) {
+        throw new IllegalArgumentException("Invalid endpoint URL");
+      }
+    }
+  }
+
+  private static URI parse(String endpointUrl) {
+    try {
+      return new URI(endpointUrl).normalize();
+    } catch (URISyntaxException e) {
+      throw new IllegalArgumentException("Invalid endpoint URL");
+    }
+  }
+
+  private static InetAddress[] resolve(String host) {
+    try {
+      return InetAddress.getAllByName(host);
+    } catch (UnknownHostException e) {
+      throw new IllegalArgumentException("Invalid endpoint URL");
+    }
+  }
+
+  private static boolean isBlockedAddress(InetAddress address) {
+    if (address.isAnyLocalAddress()
+        || address.isLoopbackAddress()
+        || address.isLinkLocalAddress()
+        || address.isSiteLocalAddress()
+        || address.isMulticastAddress()) {
+      return true;
+    }
+
+    if (isIpv6UniqueLocal(address) || isCarrierGradeNat(address) || isBenchmarkingRange(address)) {
+      return true;
+    }
+
+    byte[] raw = address.getAddress();
+    // 127.0.0.0/8
+    return raw.length == 4 && (raw[0] & 0xFF) == 127;
+  }
+
+  private static boolean isIpv6UniqueLocal(InetAddress address) {
+    if (!(address instanceof Inet6Address)) {
+      return false;
+    }
+    byte[] raw = address.getAddress();
+    // fc00::/7
+    return (raw[0] & (byte) 0xFE) == (byte) 0xFC;
+  }
+
+  private static boolean isCarrierGradeNat(InetAddress address) {
+    byte[] raw = address.getAddress();
+    // 100.64.0.0/10
+    return raw.length == 4 && (raw[0] & 0xFF) == 100 && (raw[1] & 0xC0) == 0x40;
+  }
+
+  private static boolean isBenchmarkingRange(InetAddress address) {
+    byte[] raw = address.getAddress();
+    // 198.18.0.0/15
+    return raw.length == 4 && (raw[0] & 0xFF) == 198 && ((raw[1] & 0xFF) == 18 || (raw[1] & 0xFF) == 19);
+  }
+}

